#!/usr/bin/env python3\n\"\"\"\nRisk Categorization System\nImplements advanced risk level assignment, statistical confidence intervals, and benchmarking\n\"\"\"\n\nimport logging\nimport math\nimport statistics\nfrom typing import Dict, List, Optional, Tuple, Any\nfrom dataclasses import dataclass\nfrom datetime import datetime, timedelta\nfrom enum import Enum\n\nlogger = logging.getLogger(__name__)\n\nclass RiskLevel(Enum):\n    \"\"\"Risk level enumeration\"\"\"\n    CRITICAL = \"CRITICAL\"\n    HIGH = \"HIGH\"\n    MEDIUM = \"MEDIUM\"\n    LOW = \"LOW\"\n\n@dataclass\nclass RiskThreshold:\n    \"\"\"Risk threshold definition\"\"\"\n    level: RiskLevel\n    min_score: float\n    max_score: float\n    label: str\n    color: str\n    description: str\n    action_required: str\n\n@dataclass\nclass ConfidenceInterval:\n    \"\"\"Statistical confidence interval\"\"\"\n    lower_bound: float\n    upper_bound: float\n    confidence_level: float\n    margin_of_error: float\n    sample_size: int\n\n@dataclass\nclass RiskAssessment:\n    \"\"\"Complete risk assessment result\"\"\"\n    score: float\n    risk_level: RiskLevel\n    risk_threshold: RiskThreshold\n    confidence_interval: ConfidenceInterval\n    statistical_significance: float\n    benchmark_comparison: Dict[str, Any]\n    trend_analysis: Dict[str, Any]\n    recommendations: List[str]\n\nclass RiskCategorizationEngine:\n    \"\"\"Advanced risk categorization with statistical analysis\"\"\"\n    \n    # Enhanced risk thresholds with detailed descriptions\n    RISK_THRESHOLDS = {\n        RiskLevel.CRITICAL: RiskThreshold(\n            level=RiskLevel.CRITICAL,\n            min_score=0.0,\n            max_score=40.0,\n            label=\"Critical Risk\",\n            color=\"#dc2626\",\n            description=\"Immediate action required. Significant security gaps pose severe risk to organization.\",\n            action_required=\"Emergency remediation plan within 30 days\"\n        ),\n        RiskLevel.HIGH: RiskThreshold(\n            level=RiskLevel.HIGH,\n            min_score=40.1,\n            max_score=60.0,\n            label=\"High Risk\",\n            color=\"#ea580c\",\n            description=\"Priority improvements needed. Notable security weaknesses require prompt attention.\",\n            action_required=\"Remediation plan within 90 days\"\n        ),\n        RiskLevel.MEDIUM: RiskThreshold(\n            level=RiskLevel.MEDIUM,\n            min_score=60.1,\n            max_score=80.0,\n            label=\"Medium Risk\",\n            color=\"#ca8a04\",\n            description=\"Moderate improvements recommended. Security posture is adequate but can be enhanced.\",\n            action_required=\"Improvement plan within 6 months\"\n        ),\n        RiskLevel.LOW: RiskThreshold(\n            level=RiskLevel.LOW,\n            min_score=80.1,\n            max_score=100.0,\n            label=\"Low Risk\",\n            color=\"#16a34a\",\n            description=\"Maintain current practices. Strong security posture with minor optimization opportunities.\",\n            action_required=\"Continuous monitoring and periodic review\"\n        )\n    }\n    \n    # Industry benchmark data (would be loaded from database in production)\n    INDUSTRY_BENCHMARKS = {\n        \"financial_services\": {\n            \"average_score\": 72.5,\n            \"standard_deviation\": 12.3,\n            \"sample_size\": 245,\n            \"percentiles\": {\n                \"10th\": 55.2,\n                \"25th\": 63.8,\n                \"50th\": 72.5,\n                \"75th\": 81.7,\n                \"90th\": 89.3\n            }\n        },\n        \"healthcare\": {\n            \"average_score\": 68.9,\n            \"standard_deviation\": 14.1,\n            \"sample_size\": 189,\n            \"percentiles\": {\n                \"10th\": 51.3,\n                \"25th\": 59.2,\n                \"50th\": 68.9,\n                \"75th\": 78.6,\n                \"90th\": 86.4\n            }\n        },\n        \"technology\": {\n            \"average_score\": 75.8,\n            \"standard_deviation\": 11.7,\n            \"sample_size\": 312,\n            \"percentiles\": {\n                \"10th\": 61.2,\n                \"25th\": 67.9,\n                \"50th\": 75.8,\n                \"75th\": 83.7,\n                \"90th\": 90.1\n            }\n        },\n        \"manufacturing\": {\n            \"average_score\": 64.3,\n            \"standard_deviation\": 15.8,\n            \"sample_size\": 156,\n            \"percentiles\": {\n                \"10th\": 45.7,\n                \"25th\": 53.1,\n                \"50th\": 64.3,\n                \"75th\": 75.9,\n                \"90th\": 84.2\n            }\n        },\n        \"government\": {\n            \"average_score\": 71.2,\n            \"standard_deviation\": 13.5,\n            \"sample_size\": 98,\n            \"percentiles\": {\n                \"10th\": 54.8,\n                \"25th\": 61.7,\n                \"50th\": 71.2,\n                \"75th\": 80.6,\n                \"90th\": 87.9\n            }\n        }\n    }\n    \n    @staticmethod\n    def categorize_risk(score: float, \n                       completion_rate: float = 1.0,\n                       industry: Optional[str] = None,\n                       company_size: Optional[str] = None,\n                       historical_scores: Optional[List[float]] = None) -> RiskAssessment:\n        \"\"\"Categorize risk level with statistical analysis\"\"\"\n        \n        # Determine base risk level\n        risk_level = RiskCategorizationEngine._get_risk_level(score)\n        risk_threshold = RiskCategorizationEngine.RISK_THRESHOLDS[risk_level]\n        \n        # Calculate confidence interval\n        confidence_interval = RiskCategorizationEngine._calculate_confidence_interval(\n            score, completion_rate, industry\n        )\n        \n        # Calculate statistical significance\n        statistical_significance = RiskCategorizationEngine._calculate_statistical_significance(\n            score, completion_rate, industry\n        )\n        \n        # Perform benchmark comparison\n        benchmark_comparison = RiskCategorizationEngine._compare_to_benchmarks(\n            score, industry, company_size\n        )\n        \n        # Analyze trends if historical data available\n        trend_analysis = RiskCategorizationEngine._analyze_trends(\n            score, historical_scores\n        )\n        \n        # Generate risk-specific recommendations\n        recommendations = RiskCategorizationEngine._generate_risk_recommendations(\n            risk_level, score, benchmark_comparison, trend_analysis\n        )\n        \n        return RiskAssessment(\n            score=score,\n            risk_level=risk_level,\n            risk_threshold=risk_threshold,\n            confidence_interval=confidence_interval,\n            statistical_significance=statistical_significance,\n            benchmark_comparison=benchmark_comparison,\n            trend_analysis=trend_analysis,\n            recommendations=recommendations\n        )\n    \n    @staticmethod\n    def _get_risk_level(score: float) -> RiskLevel:\n        \"\"\"Determine risk level based on score\"\"\"\n        for level, threshold in RiskCategorizationEngine.RISK_THRESHOLDS.items():\n            if threshold.min_score <= score <= threshold.max_score:\n                return level\n        return RiskLevel.CRITICAL  # Default to critical if out of range\n    \n    @staticmethod\n    def _calculate_confidence_interval(score: float, \n                                     completion_rate: float,\n                                     industry: Optional[str] = None,\n                                     confidence_level: float = 0.95) -> ConfidenceInterval:\n        \"\"\"Calculate statistical confidence interval for the score\"\"\"\n        \n        # Base margin of error from completion rate\n        completion_margin = (1 - completion_rate) * 15  # Up to 15% margin for incomplete assessments\n        \n        # Industry-specific standard deviation\n        industry_std = 12.0  # Default\n        sample_size = 100    # Default\n        \n        if industry and industry in RiskCategorizationEngine.INDUSTRY_BENCHMARKS:\n            benchmark = RiskCategorizationEngine.INDUSTRY_BENCHMARKS[industry]\n            industry_std = benchmark[\"standard_deviation\"]\n            sample_size = benchmark[\"sample_size\"]\n        \n        # Calculate statistical margin of error\n        # Using t-distribution for small samples, z-distribution for large samples\n        if sample_size >= 30:\n            # Z-score for 95% confidence\n            z_score = 1.96 if confidence_level == 0.95 else 2.576 if confidence_level == 0.99 else 1.645\n            statistical_margin = z_score * (industry_std / math.sqrt(sample_size))\n        else:\n            # T-score approximation for small samples\n            t_score = 2.0  # Approximation for 95% confidence with small samples\n            statistical_margin = t_score * (industry_std / math.sqrt(sample_size))\n        \n        # Combined margin of error\n        total_margin = math.sqrt(completion_margin**2 + statistical_margin**2)\n        \n        # Calculate bounds\n        lower_bound = max(0.0, score - total_margin)\n        upper_bound = min(100.0, score + total_margin)\n        \n        return ConfidenceInterval(\n            lower_bound=round(lower_bound, 2),\n            upper_bound=round(upper_bound, 2),\n            confidence_level=confidence_level,\n            margin_of_error=round(total_margin, 2),\n            sample_size=sample_size\n        )\n    \n    @staticmethod\n    def _calculate_statistical_significance(score: float,\n                                          completion_rate: float,\n                                          industry: Optional[str] = None) -> float:\n        \"\"\"Calculate statistical significance of the assessment\"\"\"\n        \n        # Base significance from completion rate\n        completion_significance = completion_rate\n        \n        # Industry benchmark significance\n        benchmark_significance = 0.8  # Default\n        \n        if industry and industry in RiskCategorizationEngine.INDUSTRY_BENCHMARKS:\n            benchmark = RiskCategorizationEngine.INDUSTRY_BENCHMARKS[industry]\n            sample_size = benchmark[\"sample_size\"]\n            \n            # Higher sample size = higher significance\n            benchmark_significance = min(1.0, sample_size / 200)\n        \n        # Score consistency significance (how far from boundary)\n        risk_level = RiskCategorizationEngine._get_risk_level(score)\n        threshold = RiskCategorizationEngine.RISK_THRESHOLDS[risk_level]\n        \n        # Distance from nearest boundary\n        distance_from_lower = score - threshold.min_score\n        distance_from_upper = threshold.max_score - score\n        min_distance = min(distance_from_lower, distance_from_upper)\n        \n        # Normalize distance to significance (0-1)\n        boundary_significance = min(1.0, min_distance / 10)  # 10 points = full significance\n        \n        # Combined significance\n        overall_significance = (completion_significance * 0.4 + \n                              benchmark_significance * 0.3 + \n                              boundary_significance * 0.3)\n        \n        return round(overall_significance, 3)\n    \n    @staticmethod\n    def _compare_to_benchmarks(score: float,\n                             industry: Optional[str] = None,\n                             company_size: Optional[str] = None) -> Dict[str, Any]:\n        \"\"\"Compare score to industry benchmarks\"\"\"\n        \n        comparison = {\n            \"industry_average\": None,\n            \"percentile_rank\": None,\n            \"performance_vs_peers\": None,\n            \"industry_risk_level\": None,\n            \"size_adjustment\": None\n        }\n        \n        if not industry or industry not in RiskCategorizationEngine.INDUSTRY_BENCHMARKS:\n            return comparison\n        \n        benchmark = RiskCategorizationEngine.INDUSTRY_BENCHMARKS[industry]\n        \n        # Industry average comparison\n        industry_avg = benchmark[\"average_score\"]\n        comparison[\"industry_average\"] = industry_avg\n        comparison[\"performance_vs_peers\"] = round(score - industry_avg, 2)\n        \n        # Percentile rank calculation\n        percentiles = benchmark[\"percentiles\"]\n        if score >= percentiles[\"90th\"]:\n            comparison[\"percentile_rank\"] = \"Top 10%\"\n        elif score >= percentiles[\"75th\"]:\n            comparison[\"percentile_rank\"] = \"Top 25%\"\n        elif score >= percentiles[\"50th\"]:\n            comparison[\"percentile_rank\"] = \"Above Median\"\n        elif score >= percentiles[\"25th\"]:\n            comparison[\"percentile_rank\"] = \"Below Median\"\n        else:\n            comparison[\"percentile_rank\"] = \"Bottom 25%\"\n        \n        # Industry risk level\n        industry_risk = RiskCategorizationEngine._get_risk_level(industry_avg)\n        comparison[\"industry_risk_level\"] = industry_risk.value\n        \n        # Company size adjustment (simplified)\n        if company_size:\n            size_adjustments = {\n                \"small\": -3,    # Small companies typically score 3 points lower\n                \"medium\": 0,    # Medium companies are baseline\n                \"large\": 2,     # Large companies typically score 2 points higher\n                \"enterprise\": 5 # Enterprise companies typically score 5 points higher\n            }\n            adjustment = size_adjustments.get(company_size.lower(), 0)\n            comparison[\"size_adjustment\"] = adjustment\n            comparison[\"size_adjusted_score\"] = score - adjustment\n        \n        return comparison\n    \n    @staticmethod\n    def _analyze_trends(current_score: float,\n                       historical_scores: Optional[List[float]] = None) -> Dict[str, Any]:\n        \"\"\"Analyze score trends over time\"\"\"\n        \n        trend_analysis = {\n            \"trend_direction\": None,\n            \"trend_magnitude\": None,\n            \"volatility\": None,\n            \"improvement_rate\": None,\n            \"risk_trajectory\": None\n        }\n        \n        if not historical_scores or len(historical_scores) < 2:\n            return trend_analysis\n        \n        # Add current score to historical data\n        all_scores = historical_scores + [current_score]\n        \n        # Calculate trend direction and magnitude\n        if len(all_scores) >= 3:\n            # Linear regression slope\n            n = len(all_scores)\n            x_values = list(range(n))\n            \n            # Calculate slope (trend)\n            x_mean = statistics.mean(x_values)\n            y_mean = statistics.mean(all_scores)\n            \n            numerator = sum((x - x_mean) * (y - y_mean) for x, y in zip(x_values, all_scores))\n            denominator = sum((x - x_mean) ** 2 for x in x_values)\n            \n            if denominator != 0:\n                slope = numerator / denominator\n                trend_analysis[\"trend_magnitude\"] = round(slope, 3)\n                \n                if slope > 1:\n                    trend_analysis[\"trend_direction\"] = \"Strong Improvement\"\n                elif slope > 0.5:\n                    trend_analysis[\"trend_direction\"] = \"Moderate Improvement\"\n                elif slope > -0.5:\n                    trend_analysis[\"trend_direction\"] = \"Stable\"\n                elif slope > -1:\n                    trend_analysis[\"trend_direction\"] = \"Moderate Decline\"\n                else:\n                    trend_analysis[\"trend_direction\"] = \"Strong Decline\"\n        \n        # Calculate volatility (standard deviation)\n        if len(all_scores) >= 3:\n            volatility = statistics.stdev(all_scores)\n            trend_analysis[\"volatility\"] = round(volatility, 2)\n        \n        # Calculate improvement rate (change from first to last)\n        if len(all_scores) >= 2:\n            first_score = all_scores[0]\n            last_score = all_scores[-1]\n            improvement = last_score - first_score\n            periods = len(all_scores) - 1\n            \n            improvement_rate = improvement / periods if periods > 0 else 0\n            trend_analysis[\"improvement_rate\"] = round(improvement_rate, 2)\n        \n        # Risk trajectory analysis\n        current_risk = RiskCategorizationEngine._get_risk_level(current_score)\n        if historical_scores:\n            previous_risk = RiskCategorizationEngine._get_risk_level(historical_scores[-1])\n            \n            risk_levels_order = [RiskLevel.CRITICAL, RiskLevel.HIGH, RiskLevel.MEDIUM, RiskLevel.LOW]\n            current_index = risk_levels_order.index(current_risk)\n            previous_index = risk_levels_order.index(previous_risk)\n            \n            if current_index > previous_index:\n                trend_analysis[\"risk_trajectory\"] = \"Risk Increasing\"\n            elif current_index < previous_index:\n                trend_analysis[\"risk_trajectory\"] = \"Risk Decreasing\"\n            else:\n                trend_analysis[\"risk_trajectory\"] = \"Risk Stable\"\n        \n        return trend_analysis\n    \n    @staticmethod\n    def _generate_risk_recommendations(risk_level: RiskLevel,\n                                     score: float,\n                                     benchmark_comparison: Dict[str, Any],\n                                     trend_analysis: Dict[str, Any]) -> List[str]:\n        \"\"\"Generate risk-specific recommendations\"\"\"\n        \n        recommendations = []\n        \n        # Base recommendations by risk level\n        base_recommendations = {\n            RiskLevel.CRITICAL: [\n                \"Implement emergency security measures immediately\",\n                \"Conduct comprehensive security audit within 30 days\",\n                \"Establish incident response team and procedures\",\n                \"Review and update all security policies\",\n                \"Consider engaging external security consultants\"\n            ],\n            RiskLevel.HIGH: [\n                \"Develop prioritized remediation plan within 90 days\",\n                \"Increase security monitoring and alerting\",\n                \"Conduct regular security assessments\",\n                \"Enhance employee security training programs\",\n                \"Review third-party security arrangements\"\n            ],\n            RiskLevel.MEDIUM: [\n                \"Create systematic improvement plan over 6 months\",\n                \"Implement additional security controls where feasible\",\n                \"Regular review of security metrics and KPIs\",\n                \"Consider security automation opportunities\",\n                \"Benchmark against industry best practices\"\n            ],\n            RiskLevel.LOW: [\n                \"Maintain current security practices\",\n                \"Continue regular security monitoring\",\n                \"Stay updated on emerging threats and technologies\",\n                \"Consider advanced security capabilities\",\n                \"Share best practices with industry peers\"\n            ]\n        }\n        \n        recommendations.extend(base_recommendations[risk_level])\n        \n        # Benchmark-based recommendations\n        if benchmark_comparison.get(\"performance_vs_peers\"):\n            performance_diff = benchmark_comparison[\"performance_vs_peers\"]\n            if performance_diff < -10:\n                recommendations.append(\"Focus on areas where industry peers excel\")\n                recommendations.append(\"Consider industry-specific security frameworks\")\n            elif performance_diff > 10:\n                recommendations.append(\"Share security practices with industry community\")\n                recommendations.append(\"Consider leadership role in industry security initiatives\")\n        \n        # Trend-based recommendations\n        if trend_analysis.get(\"trend_direction\"):\n            trend = trend_analysis[\"trend_direction\"]\n            if \"Decline\" in trend:\n                recommendations.append(\"Investigate causes of declining security posture\")\n                recommendations.append(\"Implement corrective measures to reverse negative trend\")\n            elif \"Improvement\" in trend:\n                recommendations.append(\"Continue current improvement initiatives\")\n                recommendations.append(\"Document successful practices for replication\")\n        \n        # Volatility-based recommendations\n        if trend_analysis.get(\"volatility\") and trend_analysis[\"volatility\"] > 10:\n            recommendations.append(\"Implement more consistent security practices\")\n            recommendations.append(\"Reduce variability in security control effectiveness\")\n        \n        return recommendations[:8]  # Limit to top 8 recommendations\n    \n    @staticmethod\n    def get_risk_matrix() -> Dict[str, Any]:\n        \"\"\"Get complete risk categorization matrix\"\"\"\n        \n        matrix = {\n            \"thresholds\": {},\n            \"industry_benchmarks\": RiskCategorizationEngine.INDUSTRY_BENCHMARKS,\n            \"statistical_methods\": {\n                \"confidence_interval\": \"95% confidence level using t-distribution\",\n                \"significance_testing\": \"Composite score based on completion rate, sample size, and boundary distance\",\n                \"trend_analysis\": \"Linear regression with volatility assessment\",\n                \"benchmark_comparison\": \"Percentile ranking against industry peers\"\n            }\n        }\n        \n        # Convert thresholds to serializable format\n        for level, threshold in RiskCategorizationEngine.RISK_THRESHOLDS.items():\n            matrix[\"thresholds\"][level.value] = {\n                \"min_score\": threshold.min_score,\n                \"max_score\": threshold.max_score,\n                \"label\": threshold.label,\n                \"color\": threshold.color,\n                \"description\": threshold.description,\n                \"action_required\": threshold.action_required\n            }\n        \n        return matrix\n\n# Create global instance\nrisk_categorization_engine = RiskCategorizationEngine()"